.@"inset-inline" => .{ .block = .{ .logical_inset, (&.{ .left, .right }) } },
.inset => .{ .block = .{ .logical_inset, (&.{ .top, .bottom, .left, .right }) } },
.@"margin-block-start" => .{ .block = .{ .logical_margin, (&.{ .@"margin-top" }) } },
