.@"padding-inline" => .{ .block = .{ .logical_padding, (&.{ .@"padding-left", .@"padding-right" }) } },
.@"border-block-start" => .{ .block = .{ .logical_borders, (&.{ .@"border-top" }) } },
.@"border-block-start-width" => .{ .block = .{ .logical_borders, (&.{ .@"border-top-width" }) } },
